module alu_16bit #(parameter DATA_WIDTH = 16) (input wire [DATA_WIDTH-1:0] a, input wire [DATA_WIDTH-1:0] b, input wire [2:0] opcode, output reg [DATA_WIDTH-1:0] result, output reg carry_out, output wire zero); assign zero = (result == {DATA_WIDTH{1'b0}}); wire is_sub; wire [DATA_WIDTH-1:0] b_op; wire adder_cin; wire adder_carry; wire [DATA_WIDTH-1:0] adder_result; assign is_sub = (opcode == 3'b001); assign b_op = b ^ {DATA_WIDTH{is_sub}}; assign adder_cin = is_sub; assign {adder_carry, adder_result} = a + b_op + { {DATA_WIDTH-1{1'b0}}, adder_cin }; wire [DATA_WIDTH-1:0] shift_left_res; wire [DATA_WIDTH-1:0] shift_right_res; assign shift_left_res = a << b[3:0]; assign shift_right_res = a >> b[3:0]; wire [DATA_WIDTH-1:0] bitwise_res; wire [DATA_WIDTH-1:0] shift_pass_res; assign bitwise_res = opcode[0] ? (opcode[1] ? (a ^ b) : (a | b)) : (opcode[1] ? {DATA_WIDTH{1'b0}} : (a & b)); assign shift_pass_res = opcode[0] ? (opcode[1] ? a : shift_left_res) : (opcode[1] ? shift_right_res : {DATA_WIDTH{1'b0}}); always @(*) begin result = {DATA_WIDTH{1'b0}}; carry_out = 1'b0; case (opcode[2]) 1'b0: begin if (opcode[1]) begin result = bitwise_res; carry_out = 1'b0; end else begin result = adder_result; carry_out = is_sub ? ~adder_carry : adder_carry; end end 1'b1: begin if (!opcode[1] && opcode[0]) begin result = bitwise_res; carry_out = 1'b0; end else begin result = shift_pass_res; carry_out = 1'b0; end end endcase end endmodule